import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.Crpw6aS5.js";const i=JSON.parse('{"title":"1959年 · 牛市喧嚣中的理性警示","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1959年.md","filePath":"05_quotes/by-year/1959年.md"}'),l={name:"05_quotes/by-year/1959年.md"};function u(q,t,s,_,c,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="_1959年-·-牛市喧嚣中的理性警示" tabindex="-1">1959年 · 牛市喧嚣中的理性警示 <a class="header-anchor" href="#_1959年-·-牛市喧嚣中的理性警示" aria-label="Permalink to &quot;1959年 · 牛市喧嚣中的理性警示&quot;">​</a></h1><blockquote><p>&quot;我不愿承受因采用&#39;新时代&#39;理念（树真的会长到天上）而面对错误的后果，可能是永久性的资本损失。&quot;——巴菲特（29岁）</p></blockquote><p>本页收录1959年致股东信中的经典语录。在&quot;蓝筹股永远上涨&quot;的声音中，巴菲特坚持认为股价包含大量投机成分，宁可承受保守的代价，也不愿追逐泡沫。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;我不愿承受因采用&#39;新时代&#39;理念（树真的会长到天上）而面对错误的后果，可能是永久性的资本损失。&quot;</p></blockquote><blockquote><p>&quot;也许其他估值标准正在演变，可能永久取代旧标准。我不这么认为。我很可能是错的；然而，我宁愿承受过度保守的惩罚，也不愿因采用&#39;新时代&#39;理念而面对错误的后果。&quot;</p></blockquote><blockquote><p>&quot;在可能的范围内，我继续尝试投资于至少部分与大盘走势无关的情形。这一策略应该在熊市带来优异表现，在牛市带来平均水平。&quot;</p></blockquote><blockquote><p>&quot;也许持有大量现金或债券在某些时期是保守的，而在其他时期则极其危险。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1959年道指上涨16.4%，但纽约证交所下跌股票多于上涨股票，投资信托公司普遍跑输指数。巴菲特在这一年明确提出：当前蓝筹股股价已包含相当大的投机成分，他宁愿保守受罚，也不愿为&quot;新时代&quot;买单。合伙企业当年平均收益25.9%，远超道指。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/1959年/翻译.html">01_letters/1959年/翻译</a> · <a href="/01_letters/1959年/核心总结.html">01_letters/1959年/核心总结</a> · <a href="/01_letters/1959年/思维导图.html">01_letters/1959年/思维导图</a></p>',15)])])}const p=e(l,[["render",u]]);export{i as __pageData,p as default};
